// NavigationView — Adw.NavigationView
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles navigation-view with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface NavigationViewProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Adw.NavigationView */
  animateTransitions?: boolean

  /** gboolean, from Adw.NavigationView */
  hhomogeneous?: boolean

  /** gboolean, from Adw.NavigationView */
  popOnEscape?: boolean

  /** gboolean, from Adw.NavigationView */
  vhomogeneous?: boolean
}

export function NavigationView({ className, children }: NavigationViewProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
